WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pf_b_profit'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '已知售价求利润', 'kp-pf-b-profit', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "已知售价求利润"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "已知售价和成本，或者已知售价和利润率，求赚了多少绝对的钱。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{利润} = \\text{售价} - \\text{成本} = \\text{成本} \\times \\text{利润率}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[题干给出售价] --> B{还给了什么?}\nB -- 给了成本 --> C[利润 = 售价 - 成本]\nB -- 给了利润率 --> D[因为 售价=成本×(1+利润率)]\nD --> E[倒推出成本 = 售价 ÷ (1+利润率)]\nE --> F[利润 = 成本 × 利润率]"}}]}$$ AS jsonb), NULL, '已知售价求利润的核心考点与实战推导。', category_node.id, CAST('["数量关系", "经济利润", "已知售价求利润"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pf_b_profit", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
